const input = Array.isArray($json) ? $json : [$json];
return input.map((job) => {
  const status = `${job.managerStatus ?? ''}`.toLowerCase();
  const eligible = job.reviewEligible === true && status.includes('happy');
  return { json: { ...job, reviewAction: eligible ? 'send-review-request' : 'manager-follow-up-first' } };
});
